		}

		public override void FireChainProjectile()
		{
			spawnPosition = parent.attackOriginTrans.position;
			if (isUltimate)
			{
				ChaosStopwatch.Stop(shotStopwatchID);
				for (int i = -5; i <= 5; i++)
				{
					if (i % 2 != 0)
					{
						CreateIceBoomerang(Globals.GetRotatedCircleVector(32, i, inputVector), i > 0);
					}
				}
			}
			else
			{
				CreateIceBoomerang(inputVector, parent.forehandAnimPlayed == parent.isFacingRight);
			}
		}

		private void CreateIceBoomerang(Vector2 givenVector, bool givenArc)
		{
			currentIB = (IceBoomerang)CreateProjectile(IceBoomerang.Prefab, spawnPosition + givenVector, Globals.GetRotationQuaternion(-givenVector));
			currentIB.Init(parent.attackOriginTrans, IsEmpowered, isUltimate, givenArc);
			FireProjectile(currentIB, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		}
	}

