18. **Порыв: область со смешанным действием.** Область растёт кругом радиуса от 0.5 до 5 м за 0.25 с линейно; множитель отбрасывания зоны падает от 50 до 15. При создании выпускается круг пыли 200 частиц радиусом 2, скоростью 25, размером 1. По окончании роста зона выключается, объект удаляется через 1 с. При попадании по сущности (не разрушаемой): если она не игнорирует замедление, на неё накладывается «порыв» как замедление-дебафф на 1.5 с со значением 0.6 (значения при касте; 2.25 с и 0.75 — лишь значения объекта по умолчанию, при касте они переопределяются) — снижение на 60 % (итог ×0.4; мод. умножить, поздний вид, сырое значение −0.6) для скорости движения и рывка. Первое такое попадание, один раз за порыв, даёт всем живым игрокам в радиусе 5 м от области баф «ускорение» (значение 0.6, т.е. +60 % скорости движения, итог ×1.6; 1.5 с, только скорость движения, не рывок) и ускоряет их перезарядки: все таймеры перезарядки уменьшаются на 2.75 с (4 с у усиленной; 2 с — значение объекта по умолчанию). Условия: баф игрокам даётся один раз за порыв; дебафф — по каждой пораженной сущности. Числа: start_radius = 0.5 м, end_radius = 5 м, grow_time = 0.25 с, knockback_start = 50, knockback_end = 15, dust_count = 200 частиц, dust_radius = 2 м, dust_speed = 25, dust_size = 1, debuff_value = 0.6 доля (при касте; мод. умножить (поздний) со значением −0.6: −60 %, итог ×0.4; у бафа значение +0.6: +60 %, итог ×1.6 (по умолчанию объекта 0.75)), buff_duration = 1.5 с (при касте (по умолчанию объекта 2.25)), cooldown_reduction = 2.75 с (при касте; 4 у усиленной (по умолчанию объекта 2)), removal_delay = 1 с. *Источник: BabylonScales.cs:1-100.*

using System;
using UnityEngine;

public class BabylonScales : MonoBehaviour
{
	private static GameObject prefab;

	private Animator anim;

	[HideInInspector]
	public Attack attack;

	private CircleCollider2D attackCollider;

	private float attackRadius = 5f;

	private ChaosQuickStopwatch attackStopwatch = new ChaosQuickStopwatch(0.25f);

	private bool attackCompleted;

	private float lerpValue;

	private bool targetHit;

	public float cdrValue = 2f;

	public float buffDuration = 2.25f;

	public float buffSpeed = 0.75f;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/BabylonScales.prefab"));

	private void Awake()
	{
		anim = GetComponent<Animator>();
		this.attack = transform.Find("Attack").GetComponent<Attack>();
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = this.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		attackCollider = this.attack.transform.GetComponent<CircleCollider2D>();
	}

	private void Start()
	{
		PoolManager.GetPoolItem<DustEmitter>().EmitCircle(200, 2f, 25f, 1f, transform.position);
		attackStopwatch.IsRunning = true;
		attackCollider.enabled = true;
		attackCompleted = false;
	}

	private void FixedUpdate()
	{
		if (!attackCompleted)
		{
			lerpValue = attackStopwatch.TimePercentage;
			attackCollider.radius = Mathf.Lerp(0.5f, attackRadius, lerpValue);
			attack.knockbackMultiplierOverride = Mathf.Lerp(50f, 15f, lerpValue);
			if (!(lerpValue < 1f))
			{
				attackCollider.enabled = false;
				attackCompleted = true;
				UnityEngine.Object.Destroy(gameObject, 1f);
			}
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (givenEnt == null || givenEnt is Destructible)
		{
			return;
		}
		if (givenEnt.health != null && !givenEnt.health.ignoreSlow.CurrentValue)
		{
			ApplyDoT(givenEnt, givenStatus: false);
		}
		if (targetHit)
		{
			return;
		}
		targetHit = true;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null) && Vector2.Distance(player.transform.position, transform.position) <= attackRadius)
			{
				ApplyDoT(player, givenStatus: true);
				player.cooldownManager.LowerAllCoolDownTimers(cdrValue, player);
			}
		}
	}

	private void ApplyDoT(Entity givenEntity, bool givenStatus)
	{
		if (givenEntity.dotManager != null)
		{
			givenEntity.dotManager.AddDot(new BabylonScalesDotEffect(givenEntity, buffDuration, buffSpeed, givenStatus));
		}
	}
}

23. **Ледяной град: метка и падение.** Область «град» ставит красную метку на земле (цвет (1, 0, 0, 0.9)) и ждёт 0.85 с, после чего проигрывает клип падения. Метка следует за объектом. В момент удара (кадр клипа): тряска камеры ×1, 50 ледяных осколков, звук взрыва льда, метка сбрасывается сразу, объект удаляется через 0.25 с. Таймер падения заводится только в режиме с меткой (по умолчанию включён). Условия: таймер падения стартует только при включённой метке. Числа: fall_delay = 0.85 с, shards = 50 частиц, removal_delay = 0.25 с. *Источник: ArrowShower.cs:1-70.*
25. **Пул кругов предупреждения.** Один общий пул из 25 кругов, выдаются по кругу (индекс +1 с возвратом в 0). Если размер не задан по обеим осям — 4×4; если задан по одной оси — второй равен первому. Пул создаётся один раз и сохраняется между сценами; второй экземпляр уничтожается. Все круги переиспользуются, повторная выдача занятого круга перезаписывает его. Числа: pool_size = 25, default_size = 4 м. *Источник: CastingCirclePool.cs:1-80.*
