private void AddWinToken(int playerID, Color capeColor)
{
	playerID = Mathf.Clamp(playerID, 0, 1);
	GameObject gameObject = Object.Instantiate(winCountTokenPrefab);
	RectTransform component = gameObject.GetComponent<RectTransform>();
	gameObject.transform.SetParent(winCountTransform[playerID]);
	float num = 0.14f * (float)(playerWinCounts[playerID] - 1);
	num = ((playerID != 0) ? (1f - num - 0.14f) : num);
	component.anchorMin = new Vector2(num, 0f);
	component.anchorMax = new Vector2(num + 0.14f, 1f);
	component.offsetMin = Vector2.zero;
	component.offsetMax = Vector2.zero;
	gameObject.transform.Find("CapeColor").GetComponent<Image>().color = capeColor * 1.4f;
	capeColor *= 0.4f;
	capeColor.a = 1f;
	gameObject.transform.Find("Circle").GetComponent<Image>().color = capeColor;
	gameObject.GetComponent<Animator>().Play("Spawn");
}

